-- export-projection-docs.sql - Exports authoritative PostgreSQL state into
-- NDJSON files for OpenSearch projection indexing (ADR-0002).

\set ON_ERROR_STOP on

\copy (SELECT row_to_json(t) FROM (SELECT s.id AS store_id, r.slug AS retailer_slug, r.name AS retailer_name, s.external_key, s.name, s.address, s.city, COUNT(oc.retailer_product_id)::int AS active_offers_count, MAX(oc.published_ts) AS latest_published_ts FROM stores s JOIN retailers r ON r.id = s.retailer_id LEFT JOIN offers_current oc ON oc.store_id = s.id GROUP BY s.id, r.slug, r.name, s.external_key, s.name, s.address, s.city ORDER BY s.id) t) TO '/tmp/aishopping/projection_stores.ndjson'

\copy (SELECT row_to_json(t) FROM (SELECT (oc.store_id::text || ':' || oc.retailer_product_id::text) AS offer_id, oc.store_id, s.external_key AS store_external_key, s.name AS store_name, s.city, r.id AS retailer_id, r.slug AS retailer_slug, r.name AS retailer_name, oc.retailer_product_id, rp.sku_key, rp.listing_name, UPPER(rp.listing_name) AS normalized_name, rp.category, cp.id AS canonical_product_id, cp.canonical_key, cp.canonical_name, cp.normalized_size, trim(oc.currency) AS currency, oc.price_current, oc.unit_price, oc.unit_label, oc.regular_price, oc.discount_price, oc.discount_pct, oc.promo_type, oc.promo_starts_on, oc.promo_ends_on, (oc.promo_type IS NOT NULL AND oc.promo_type <> '') AS is_promo, oc.availability, oc.published_ts, oc.fetched_ts, oc.source_url, oc.run_id FROM offers_current oc JOIN stores s ON s.id = oc.store_id JOIN retailers r ON r.id = s.retailer_id JOIN retailer_products rp ON rp.id = oc.retailer_product_id LEFT JOIN product_matches pm ON pm.retailer_product_id = rp.id AND pm.review_status IN ('auto_accepted', 'approved') LEFT JOIN canonical_products cp ON cp.id = pm.canonical_product_id ORDER BY oc.store_id, oc.retailer_product_id) t) TO '/tmp/aishopping/projection_offers.ndjson'

\copy (SELECT row_to_json(t) FROM (WITH per_retailer AS (SELECT cp.id AS canonical_product_id, r.slug AS retailer_slug, rp.id AS retailer_product_id, rp.listing_name, MIN(oc.price_current) AS min_price, MAX(oc.price_current) AS max_price, COUNT(DISTINCT oc.store_id)::int AS store_count, MAX(oc.published_ts) AS latest_published_ts, MIN(oc.source_url) AS source_url FROM canonical_products cp JOIN product_matches pm ON pm.canonical_product_id = cp.id AND pm.review_status IN ('auto_accepted', 'approved') JOIN retailer_products rp ON rp.id = pm.retailer_product_id JOIN retailers r ON r.id = rp.retailer_id JOIN offers_current oc ON oc.retailer_product_id = rp.id GROUP BY cp.id, r.slug, rp.id, rp.listing_name) SELECT cp.id AS canonical_product_id, cp.canonical_key, cp.canonical_name, cp.normalized_tokens, cp.normalized_size, cp.quantity_value, cp.quantity_unit, cp.pack_count, cp.gtin, COUNT(DISTINCT pr.retailer_slug)::int AS retailer_count, COALESCE(SUM(pr.store_count), 0)::int AS store_count, COALESCE(ARRAY_AGG(DISTINCT pr.retailer_slug ORDER BY pr.retailer_slug) FILTER (WHERE pr.retailer_slug IS NOT NULL), ARRAY[]::text[]) AS retailers, MIN(pr.min_price) AS min_price, MAX(pr.max_price) AS max_price, (MAX(pr.max_price) - MIN(pr.min_price)) AS spread_mkd, MAX(pr.latest_published_ts) AS latest_published_ts, COALESCE(JSON_AGG(JSON_BUILD_OBJECT('retailer_slug', pr.retailer_slug, 'retailer_product_id', pr.retailer_product_id, 'listing_name', pr.listing_name, 'min_price', pr.min_price, 'max_price', pr.max_price, 'store_count', pr.store_count, 'latest_published_ts', pr.latest_published_ts, 'source_url', pr.source_url) ORDER BY pr.min_price, pr.retailer_slug) FILTER (WHERE pr.retailer_slug IS NOT NULL), '[]'::json) AS offers FROM canonical_products cp LEFT JOIN per_retailer pr ON pr.canonical_product_id = cp.id GROUP BY cp.id, cp.canonical_key, cp.canonical_name, cp.normalized_tokens, cp.normalized_size, cp.quantity_value, cp.quantity_unit, cp.pack_count, cp.gtin ORDER BY cp.id) t) TO '/tmp/aishopping/projection_products.ndjson'
